import { motion } from "framer-motion";
import { useState } from "react";

export default function Contact() {
  const [form, setForm] = useState({
    name: "",
    email: "",
    phone: "",
    experience: "",
    specialization: "",
    message: "",
  });

  const [status, setStatus] = useState("");

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setStatus("Submitting...");

    try {
      const res = await fetch("http://localhost:5001/api/trainers/apply", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(form),
      });

      if (res.ok) {
        setStatus("Application submitted successfully ✅");
        setForm({
          name: "",
          email: "",
          phone: "",
          experience: "",
          specialization: "",
          message: "",
        });
      } else {
        setStatus("Something went wrong ❌");
      }
    } catch {
      setStatus("Server error ❌");
    }
  };

  return (
    <section
      id="contact"
      className="relative bg-black py-32 px-6 overflow-hidden"
    >
      {/* SOFT BACKGROUND GLOWS */}
      <div className="absolute -top-32 -left-32 w-[420px] h-[420px] bg-[#e9b21a]/10 blur-[140px]" />
      <div className="absolute -bottom-32 -right-32 w-[420px] h-[420px] bg-[#e9b21a]/10 blur-[140px]" />

      <div className="relative max-w-7xl mx-auto grid lg:grid-cols-2 gap-20 items-center">

        {/* LEFT CONTENT – STATIC, PREMIUM */}
        <div className="space-y-8">
          <h2 className="text-4xl md:text-5xl font-bold leading-tight">
            Become a <span className="text-[#e9b21a]">Bodyzeal Trainer</span>
          </h2>

          <p className="text-gray-400 max-w-lg">
            We are building a team of elite fitness professionals who inspire,
            transform, and lead by example — not just trainers.
          </p>

          <div className="space-y-4 text-sm text-gray-300">
            <div className="flex gap-3">
              <span className="text-[#e9b21a]">✦</span>
              Premium facilities & high-quality clientele
            </div>
            <div className="flex gap-3">
              <span className="text-[#e9b21a]">✦</span>
              Brand recognition & long-term career growth
            </div>
            <div className="flex gap-3">
              <span className="text-[#e9b21a]">✦</span>
              Respect, performance-based income & stability
            </div>
          </div>

          <p className="text-xs text-gray-500">
            Every application is reviewed personally by our leadership team.
          </p>
        </div>

        {/* FORM – SOFT FADE ONLY (NO REVEAL FEEL) */}
        <motion.form
          onSubmit={handleSubmit}
          initial={{ opacity: 0 }}
          whileInView={{ opacity: 1 }}
          viewport={{ once: true }}
          transition={{ duration: 0.6 }}
          className="relative bg-white/5 backdrop-blur-xl border border-white/10 rounded-3xl p-10"
        >
          {/* BORDER GLOW */}
          <div className="absolute inset-0 rounded-3xl ring-1 ring-[#e9b21a]/20 pointer-events-none" />

          <div className="space-y-4">
            <input
              name="name"
              placeholder="Full Name"
              value={form.name}
              onChange={handleChange}
              required
              className="w-full bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none"
            />

            <input
              type="email"
              name="email"
              placeholder="Email Address"
              value={form.email}
              onChange={handleChange}
              required
              className="w-full bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none"
            />

            <input
              name="phone"
              placeholder="Phone Number"
              value={form.phone}
              onChange={handleChange}
              required
              className="w-full bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none"
            />

            <input
              name="experience"
              placeholder="Years of Experience"
              value={form.experience}
              onChange={handleChange}
              required
              className="w-full bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none"
            />

            <input
              name="specialization"
              placeholder="Specialization (PT / Yoga / Zumba etc.)"
              value={form.specialization}
              onChange={handleChange}
              required
              className="w-full bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none"
            />

            <textarea
              name="message"
              rows="4"
              placeholder="Tell us about your certifications & mindset"
              value={form.message}
              onChange={handleChange}
              required
              className="w-full bg-black/80 border border-white/15 rounded-xl px-4 py-3 focus:border-[#e9b21a] outline-none resize-none"
            />
          </div>

          <button
            type="submit"
            className="mt-6 w-full py-3 rounded-full bg-[#e9b21a] text-black font-semibold hover:bg-[#d4a018] transition"
          >
            Apply as Trainer
          </button>

          {status && (
            <p className="mt-4 text-center text-sm text-gray-400">
              {status}
            </p>
          )}
        </motion.form>
      </div>
    </section>
  );
}
